function check([expression], actual, expected) {
  if (typeof actual !== 'string') return false;
  const plus = expression.indexOf('+');
  const values = new Map();
  for (let i = 0; i < plus; i++) {
    for (let j = plus + 2; j <= expression.length; j++) {
      const before = i === 0 ? 1 : Number(expression.slice(0, i));
      const after = j === expression.length ? 1 : Number(expression.slice(j));
      const [b, c] = expression.slice(i, j).split('+').map(Number);
      values.set(expression.slice(0, i) + '(' + expression.slice(i, j) + ')' + expression.slice(j), before * (b + c) * after);
    }
  }
  return values.has(actual) && values.has(expected) && values.get(actual) === values.get(expected);
}

