function validate([expression]) {
  if (typeof expression !== 'string') return 'expression must be a string.';
  if (expression.length < 3 || expression.length > 10) return 'expression has 3 to 10 characters.';
  if (!/^[1-9]+\+[1-9]+$/.test(expression)) return 'Use digits 1-9 around exactly one "+", like "247+38".';
  return null;
}

