function minimizeResult(expression) {
  // Build every bracketed string, then evaluate it with a tiny parser that treats juxtaposition as multiplication.
  const evaluate = (text) => {
    let pos = 0;
    const factor = () => {
      if (text[pos] === '(') {
        pos++;
        const inside = sum();
        pos++;
        return inside;
      }
      let digits = '';
      while (pos < text.length && text[pos] >= '0' && text[pos] <= '9') digits += text[pos++];
      return Number(digits);
    };
    const product = () => {
      let result = factor();
      while (pos < text.length && text[pos] !== '+' && text[pos] !== ')') result *= factor();
      return result;
    };
    const sum = () => {
      let result = product();
      while (text[pos] === '+') { pos++; result += product(); }
      return result;
    };
    return sum();
  };
  const plus = expression.indexOf('+');
  let best = null, bestValue = Infinity;
  for (let open = 0; open < plus; open++)
    for (let close = plus + 2; close <= expression.length; close++) {
      const text = expression.slice(0, open) + '(' + expression.slice(open, close) + ')' + expression.slice(close);
      const value = evaluate(text);
      if (value < bestValue) { bestValue = value; best = text; }
    }
  return best;
}

