function generate(rand, size) {
  const digits = (count) => Array.from({ length: count }, () => 1 + Math.floor(rand() * 9)).join('');
  const total = size === 'large' ? 7 + Math.floor(rand() * 3) : 2 + Math.floor(rand() * 6);
  const first = 1 + Math.floor(rand() * (total - 1));
  return [digits(first) + '+' + digits(total - first)];
}
